package ociresources

import (
	"errors"
	"strings"
	"testing"

	"github.com/anthnel/devdesk/internal/docker"
	sharedcomponents "github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/keymap"
	"github.com/anthnel/devdesk/internal/ui/testutil"
)

// §3.22 extended to the four tabs. Every action here is a `docker` invocation
// that takes seconds, and the row used to be identical to one where nothing was
// happening.

// removeSelected walks the confirm modal for the tab the model is on.
func removeSelected(t *testing.T, m Model) Model {
	t.Helper()
	return feed(t, m, testutil.Key(keymap.Delete), sharedcomponents.ConfirmModalYesMsg{})
}

// busyCell returns the drawn line for a row, where the spinner override lives —
// it is applied at render time so the stored cells do not go stale as the frame
// advances.
func renderedRow(t *testing.T, view, name string) string {
	t.Helper()
	for _, line := range strings.Split(view, "\n") {
		if strings.Contains(line, name) {
			return line
		}
	}
	t.Fatalf("no rendered row for %q in:\n%s", name, view)
	return ""
}

func TestRemovingAnImageBlinksItsDotAndKeepsItsID(t *testing.T) {
	m := removeSelected(t, loadedModel(t))
	img := m.imageTable.Items()[0] // fixtures arrive in this order

	if !m.imageTable.IsBusy(img.Image.ID) {
		t.Fatal("the removal was not marked on the row")
	}
	// DEVDESK-146: the activity column carries the removal, so the ID cell is
	// no longer spent on a spinner and the row keeps saying which image it is.
	m.advanceBusySpinners()
	line := renderedRow(t, m.imageTable.View(), img.RawName)
	if !strings.Contains(line, shortID(img.Image.ID)) {
		t.Errorf("the removing row lost its ID:\n%s", line)
	}
	if !strings.Contains(line, img.RawName) {
		t.Errorf("the removing row lost the name that says which image it is:\n%s", line)
	}
	if hasSpinnerFrame(line) {
		t.Errorf("the removing row still carries a spinner frame:\n%s", line)
	}
	if got := m.actionLine(); !strings.Contains(got, img.RawName) {
		t.Errorf("actionLine = %q, want it to name the image", got)
	}
}

// The marker has to be lifted on every outcome. Only the success path would
// leave the row spinning for the life of the view.
func TestAFailedImageRemovalStillLiftsTheMarker(t *testing.T) {
	m := removeSelected(t, loadedModel(t))
	id := m.imageTable.Items()[0].Image.ID

	m = feed(t, m, ImageActionMsg{Action: "remove", ID: id, Name: "api:v1", Err: errors.New("image is in use")})

	if m.imageTable.IsBusy(id) {
		t.Error("the marker survived a failed removal: the row spins for good")
	}
	if !m.footer.IsSet() {
		t.Error("a failed removal reported nothing")
	}
}

// Confirming twice on the same image used to issue two `docker rmi`; the second
// fails with "no such image" on a removal that worked.
func TestASecondRemovalOfTheSameImageIsRefused(t *testing.T) {
	m := removeSelected(t, loadedModel(t))

	m, _ = step(t, m, testutil.Key(keymap.Delete))

	if m.confirmModal != nil {
		t.Error("a second removal opened its confirmation while the first was running")
	}
	if m.footer.Text() != busyMessage {
		t.Errorf("footer = %q, want the busy message", m.footer.Text())
	}
}

func TestRemovingANetworkSpinsItsRow(t *testing.T) {
	m := removeSelected(t, feed(t, loadedModel(t), testutil.Key("tab")))
	net := m.networkTable.Items()[0]

	if !m.networkTable.IsBusy(net.ID) {
		t.Fatal("the removal was not marked on the row")
	}
	if line := renderedRow(t, m.networkTable.View(), net.Name); strings.Contains(line, shortID(net.ID)) {
		t.Errorf("the removing row still shows its ID:\n%s", line)
	}

	m = feed(t, m, NetworkActionMsg{Action: "remove", ID: net.ID})
	if m.networkTable.IsBusy(net.ID) {
		t.Error("the marker outlived the removal")
	}
}

// A volume has no ID, so its name is its identity — which is also why the
// spinner cannot go there and takes the Driver cell instead.
func TestRemovingAVolumeSpinsItsRowAndKeepsItsName(t *testing.T) {
	m := removeSelected(t, feed(t, loadedModel(t), testutil.Key("tab"), testutil.Key("tab")))
	vol := m.volumeTable.Items()[0]

	if !m.volumeTable.IsBusy(vol.Name) {
		t.Fatal("the removal was not marked on the row")
	}
	line := renderedRow(t, m.volumeTable.View(), vol.Name)
	if strings.Contains(line, vol.Driver) {
		t.Errorf("the removing row still shows its driver:\n%s", line)
	}
	if !strings.Contains(line, vol.Name) {
		t.Errorf("the removing row lost its name, which is the only thing that says which volume it is:\n%s", line)
	}

	m = feed(t, m, VolumeActionMsg{Action: "remove", Name: vol.Name})
	if m.volumeTable.IsBusy(vol.Name) {
		t.Error("the marker outlived the removal")
	}
}

// Logged is exactly the answer a login or logout is about to change, so it is
// the cell to spend while one runs. U picks the direction from that same cell,
// which is why the status has to be seeded here (§3.26).
func TestALogoutSpinsTheLoggedCell(t *testing.T) {
	m := registriesTab(t)
	reg := m.registries[0]
	m = feed(t, m,
		RegistryLoginStatusMsg{Status: map[string]docker.LoginState{reg.URL: docker.LoginHelper}},
		testutil.Key(keymap.Auth))

	if !m.registryTable.IsBusy(reg.URL) {
		t.Fatal("the logout was not marked on the row")
	}
	if got := m.actionLine(); !strings.Contains(got, "Logging out") {
		t.Errorf("actionLine = %q, want it to name the logout", got)
	}

	m = feed(t, m, RegistryLogoutCompleteMsg{RegistryURL: reg.URL})
	if m.registryTable.IsBusy(reg.URL) {
		t.Error("the marker outlived the logout")
	}
}

// An action started on one tab goes on running after `tab`. A spinner that
// stopped turning because the user looked elsewhere would read as a hang.
func TestTheFrameTurnsForAnActionOnAnotherTab(t *testing.T) {
	m := removeSelected(t, loadedModel(t))
	m = feed(t, m, testutil.Key("tab")) // networks

	if len(m.busyLabels()) != 1 {
		t.Fatalf("busyLabels = %v, want the image removal still counted", m.busyLabels())
	}
	if !m.advanceBusySpinners() {
		t.Error("the spinner tick stopped being scheduled while an action was running")
	}
}

// A prune acts on no row, so marking every row would say something false. It
// gets a line of its own.
func TestAPruneSaysSoWithoutMarkingAnyRow(t *testing.T) {
	m := feed(t, loadedModel(t), testutil.Key(keymap.Prune), sharedcomponents.ConfirmModalYesMsg{})
	if m.pruning != "images" {
		t.Fatalf("pruning = %q after confirming, want the images prune marked", m.pruning)
	}

	if len(m.busyLabels()) != 0 {
		t.Errorf("a prune marked %v, want no row marked", m.busyLabels())
	}
	if got := m.actionLine(); !strings.Contains(got, "Pruning") {
		t.Errorf("actionLine = %q, want the prune named", got)
	}

	m = feed(t, m, PruneCompleteMsg{Output: "reclaimed 1.2GB"})
	if m.pruning != "" {
		t.Errorf("pruning = %q after the prune landed, want it cleared", m.pruning)
	}
}
package ociresources

import (
	"fmt"

	tea "github.com/charmbracelet/bubbletea"
)

// Rows an action is running on, across the four tabs (§3.22).
//
// Every action here is a `docker` invocation that can take seconds — removing a
// large image, a network the daemon is still tearing connections off, a
// `docker login` that has to reach a registry over a slow link. Nothing said so:
// the row was identical to one with nothing happening to it.
//
// The Images table shows it in its activity column (blinking dot); the other
// tables spend a cell on a spinner, the one the user does not need while the
// action runs. §3.16 settled why it is a cell and not a column of its own — a
// column costs cells on every screen to say nothing on all but one row, and at
// 80 columns this view has none to spare.

// busyMessage is what every tab says when an action is already running on the
// selected row. One message rather than one per verb, because the user's next
// move is the same in all of them: wait.
const busyMessage = "Already busy — an action is running on this row"

// advanceBusySpinners moves the spinner frame of the Networks, Volumes and
// Registries tables on (Images has none) and reports whether anything is
// running on any tab. It is called from the spinner tick, which is what keeps
// the frames turning; the tick has to go on being scheduled while this returns
// true, or the spinner stops on a row that is still working.
func (m *Model) advanceBusySpinners() bool {
	m.networkTable.AdvanceSpinner()
	m.volumeTable.AdvanceSpinner()
	m.registryTable.AdvanceSpinner()
	return len(m.busyLabels()) > 0
}

// busyLabels gathers what is running across every tab.
//
// Across all four rather than the active one: an action started on the Images
// tab goes on running after `tab`, and a spinner that stopped turning because
// the user looked elsewhere would read as a hang on the way back.
func (m Model) busyLabels() []string {
	var out []string
	out = append(out, m.imageTable.BusyLabels()...)
	out = append(out, m.networkTable.BusyLabels()...)
	out = append(out, m.volumeTable.BusyLabels()...)
	out = append(out, m.registryTable.BusyLabels()...)
	return out
}

// actionLine names what is running, in words. The spinner on the row says that
// something is; this says what.
//
// Rendered from the current state rather than assigned to a footer message,
// because a footer message expires after three seconds (Rule 128) and these
// outlive that — the same reason §3.17's sync progress is a rendered line.
func (m Model) actionLine() string {
	if m.pruning != "" {
		return "Pruning " + m.pruning + "…"
	}
	labels := m.busyLabels()
	switch len(labels) {
	case 0:
		return ""
	case 1:
		return labels[0] + "…"
	default:
		// Naming them all would run past the line; the count is what the user
		// is waiting on anyway.
		return fmt.Sprintf("%d actions running…", len(labels))
	}
}

// busyTick is what an action returns alongside its command so the frames turn.
// Init starts a tick, but it stops as soon as nothing is loading, and an action
// begun after that would sit on a frozen frame.
func (m Model) busyTick() tea.Cmd { return m.spinner.Tick }
package ociresources

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// ociKinds are the operations whose activity or remembered failure an Images
// row shows: a scan or a pull, whoever started it (D5).
var ociKinds = []jobs.Kind{jobs.KindScan, jobs.KindPull}

// rowActivity resolves what one Images row says about its activity, read from
// the router snapshot against the context it carries. The identity is the raw
// reference, never a canonical form. A removal in flight is this view's own
// observation: it is reported as Running with its label.
func (m Model) rowActivity(r imageRow) components.RowActivity {
	q := components.RowQuery{
		Runs: m.jobs, Failures: m.failures, Context: m.contextName,
		Target: jobs.TargetKey(r.RawName), Kinds: ociKinds,
	}
	if label, ok := m.imageTable.BusyLabel(r.Image.ID); ok {
		q.Observed = indicator.Running
		q.ObservedText = label
	}
	return components.DescribeRow(q)
}

// scanRunning reports whether a scan of the image is running now in the
// current context. A queued scan is not running.
func (m Model) scanRunning(name string) bool { return m.runningOn(name, jobs.KindScan) }

// pullRunning reports whether a pull of the image is running now in the
// current context. A queued pull is not running.
func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }

func (m Model) runningOn(name string, kind jobs.Kind) bool {
	for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"oci/images": &m.imageTable}
}
package ociresources

import (
	"reflect"
	"strings"
	"testing"

	"github.com/charmbracelet/bubbles/spinner"

	"github.com/anthnel/devdesk/internal/jobs"
)

// ── DEVDESK-146: a frame sets the blink phase, nothing else ──────────────────

// hasSpinnerFrame reports whether s carries one of the Dot spinner's frames.
func hasSpinnerFrame(s string) bool {
	for _, f := range spinner.Dot.Frames {
		if strings.Contains(s, f) {
			return true
		}
	}
	return false
}

func TestAFrameSetsThePhaseWithoutRebuildingRows(t *testing.T) {
	m := loadedModel(t)
	m = scanning(t, m, m.images[0].Name())
	before := reflect.ValueOf(m.imageTable.Items()).Pointer()
	nRuns := len(m.jobs)

	m = feed(t, m, jobs.FrameMsg{Blink: false})
	if m.imageTable.BlinkPhase() {
		t.Error("Blink=false left the phase on")
	}
	m = feed(t, m, jobs.FrameMsg{Blink: true})
	if !m.imageTable.BlinkPhase() {
		t.Error("Blink=true did not turn the phase back on")
	}
	if after := reflect.ValueOf(m.imageTable.Items()).Pointer(); after != before {
		t.Error("a frame rebuilt the rows; the phase is read at render")
	}
	if len(m.jobs) != nRuns {
		t.Errorf("the held runs went from %d to %d on a frame", nRuns, len(m.jobs))
	}
}

func TestAFrameNeverReachesTheTableCells(t *testing.T) {
	m := loadedModel(t)
	m = scanning(t, m, m.images[0].Name())
	m = feed(t, m, jobs.FrameMsg{Frame: "ZZ", RenderedFrame: "FOOTERFRAME", Blink: true})
	if strings.Contains(m.View(), "ZZ") {
		t.Error("the bare frame still reaches the table")
	}
}

func TestTheModelHoldsNoRowSpinnerState(t *testing.T) {
	if _, ok := reflect.TypeOf(Model{}).FieldByName("jobFrame"); ok {
		t.Error("Model still carries jobFrame")
	}
	row := reflect.TypeOf(imageRow{})
	for _, name := range []string{"Scanning", "Pulling", "SpinnerFrame"} {
		if _, ok := row.FieldByName(name); ok {
			t.Errorf("imageRow still carries %s", name)
		}
	}
	for _, name := range []string{"Activity", "ScanRunning", "PullRunning"} {
		if _, ok := row.FieldByName(name); !ok {
			t.Errorf("imageRow lacks %s", name)
		}
	}
}
