// the frames turning; the tick has to go on being scheduled while this returns
// true, or the spinner stops on a row that is still working.
func (m *Model) advanceBusySpinners() bool {
	m.networkTable.AdvanceSpinner()
	m.volumeTable.AdvanceSpinner()
	m.registryTable.AdvanceSpinner()
	return len(m.busyLabels()) > 0
}

// busyLabels gathers what is running across every tab.
//
// Across all four rather than the active one: an action started on the Images
// tab goes on running after `tab`, and a spinner that stopped turning because
// the user looked elsewhere would read as a hang on the way back.
func (m Model) busyLabels() []string {
	var out []string
	out = append(out, m.imageTable.BusyLabels()...)
	out = append(out, m.networkTable.BusyLabels()...)
	out = append(out, m.volumeTable.BusyLabels()...)
	out = append(out, m.registryTable.BusyLabels()...)
	return out
}

// actionLine names what is running, in words. The spinner on the row says that
// something is; this says what.
//
// Rendered from the current state rather than assigned to a footer message,
// because a footer message expires after three seconds (Rule 128) and these
// outlive that — the same reason §3.17's sync progress is a rendered line.
func (m Model) actionLine() string {
	if m.pruning != "" {
		return "Pruning " + m.pruning + "…"
	}
	labels := m.busyLabels()
	switch len(labels) {
	case 0:
		return ""
	case 1:
		return labels[0] + "…"
	default:
		// Naming them all would run past the line; the count is what the user
		// is waiting on anyway.
		return fmt.Sprintf("%d actions running…", len(labels))
	}
}

// busyTick is what an action returns alongside its command so the frames turn.
// Init starts a tick, but it stops as soon as nothing is loading, and an action
// begun after that would sit on a frozen frame.
func (m Model) busyTick() tea.Cmd { return m.spinner.Tick }
package ociresources

import (
	"github.com/anthnel/devdesk/internal/jobs"
	"github.com/anthnel/devdesk/internal/ui/components"
	"github.com/anthnel/devdesk/internal/ui/datatable"
	"github.com/anthnel/devdesk/internal/ui/indicator"
)

// ociKinds are the operations whose activity or remembered failure an Images
// row shows: a scan or a pull, whoever started it (D5).
var ociKinds = []jobs.Kind{jobs.KindScan, jobs.KindPull}

// rowActivity resolves what one Images row says about its activity, read from
// the router snapshot against the context it carries. The identity is the raw
// reference, never a canonical form. A removal in flight is this view's own
// observation: it is reported as Running with its label.
func (m Model) rowActivity(r imageRow) components.RowActivity {
	q := components.RowQuery{
		Runs: m.jobs, Failures: m.failures, Context: m.contextName,
		Target: jobs.TargetKey(r.RawName), Kinds: ociKinds,
	}
	if label, ok := m.imageTable.BusyLabel(r.Image.ID); ok {
		q.Observed = indicator.Running
		q.ObservedText = label
	}
	return components.DescribeRow(q)
}

// scanRunning reports whether a scan of the image is running now in the
// current context. A queued scan is not running.
func (m Model) scanRunning(name string) bool { return m.runningOn(name, jobs.KindScan) }

// pullRunning reports whether a pull of the image is running now in the
// current context. A queued pull is not running.
func (m Model) pullRunning(name string) bool { return m.runningOn(name, jobs.KindPull) }

func (m Model) runningOn(name string, kind jobs.Kind) bool {
	for _, a := range jobs.ActiveOn(m.jobs, m.contextName, name, kind) {
		if a.Item.State == jobs.ItemRunning {
			return true
		}
	}
	return false
}

// ActivityTables returns the read-only face of the view's table, keyed by the
// name the activity-column guard (internal/app) knows it by. Tests only.
func (m Model) ActivityTables() map[string]datatable.ActivityTable {
	return map[string]datatable.ActivityTable{"oci/images": &m.imageTable}
}
