}

func TestImageColumnsFitTheWidthWithTheCFGColumn(t *testing.T) {
	cfg := testConfig()
	cfg.Scan.Categories.Misconfig.Enabled = true
	for _, width := range []int{60, 70, 80, 90, 110, 140, 200} {
		m := feed(t, New(cfg), tea.WindowSizeMsg{Width: width, Height: 30}, ImagesListMsg{Images: imageFixtures()})
		if got, want := m.imageTable.RenderedWidth(), width-2; got != want {
			t.Errorf("width %d with CFG: the line spans %d, want %d", width, got, want)
		}
		if got := visibleImageColumns(m); got[0] != glyphDot || got[1] != "ID" {
			t.Errorf("width %d with CFG: columns start %v, want [● ID …]", width, got)
		}
	}
	m := feed(t, New(cfg), tea.WindowSizeMsg{Width: 200, Height: 30}, ImagesListMsg{Images: imageFixtures()})
	got := visibleImageColumns(m)
	if i := slices.Index(got, "CFG"); i < 0 || got[i-1] != "L" || got[i+1] != "Scanned" {
		t.Errorf("at 200 the CFG column is misplaced: %v", got)
	}
}

// The real removal flow marks the row busy in Update() without rebuilding the
// Span is one coloured run of a multi-run cell (Column.Spans): Width cells of
// the cell's already-fitted text, painted with Style. Style must not carry
// Width, Padding or Margin: they would change the cell's width (as for Cut).
type Span struct {
	Width int
	Style lipgloss.Style
}

// IndicatorColumn builds the activity column (Rule 125 shape: untitled, fixed,
// IconColumnWidth). It is the only way a view builds one. Only the first column
// carrying an Indicator is honoured (Model.indicatorAt); later ones are ignored.
func IndicatorColumn[T any](state func(T) indicator.State,
	rest func(T) string, restStyle func(T) lipgloss.Style) Column[T] {
	c := Column[T]{
		Sizing: SizingFixed, MinWidth: IconColumnWidth,
		Indicator: state,
		Cell: func(item T) string {
			if rest == nil {
				return ""
			}
			return rest(item)
		},
	}
	if restStyle != nil {
		c.Style = restStyle
	}
	return c
}

// SetBlinkPhase sets the phase read at render. Read at render; nothing is rebuilt.
func (m *Model[T]) SetBlinkPhase(on bool) { m.blinkOn = on }

// BlinkPhase reports the current blink phase.
func (m *Model[T]) BlinkPhase() bool { return m.blinkOn }
